import { type AudioPlayer, createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import { AppState } from 'react-native';
import { useSettingsStore } from '../stores/settingsStore';

/**
 * Sound effects and background music (expo-audio). All files are original, generated by
 * `scripts/make-sounds.py`. Effects respect the "Sound" setting, the loop the "Music" one.
 */
const EFFECTS = {
  tap: require('../../assets/sounds/tap.wav'),
  correct: require('../../assets/sounds/correct.wav'),
  ding: require('../../assets/sounds/ding.wav'),
  close: require('../../assets/sounds/close.wav'),
  tick: require('../../assets/sounds/tick.wav'),
  start: require('../../assets/sounds/start.wav'),
  reveal: require('../../assets/sounds/reveal.wav'),
  sent: require('../../assets/sounds/sent.wav'),
  gameover: require('../../assets/sounds/gameover.wav'),
  error: require('../../assets/sounds/error.wav'),
} as const;

export type SoundName = keyof typeof EFFECTS;

const MUSIC_VOLUME = 0.25;
const EFFECT_VOLUME = 0.8;

const players = new Map<SoundName, AudioPlayer>();
let music: AudioPlayer | null = null;
let foreground = AppState.currentState === 'active';

function effectPlayer(name: SoundName): AudioPlayer {
  let player = players.get(name);
  if (!player) {
    player = createAudioPlayer(EFFECTS[name]);
    player.volume = EFFECT_VOLUME;
    players.set(name, player);
  }
  return player;
}

/** Plays a short effect from the start (restarts it if it is already playing). */
export function playSound(name: SoundName): void {
  if (!useSettingsStore.getState().sound) return;
  try {
    const player = effectPlayer(name);
    void player.seekTo(0).catch(() => {});
    player.play();
  } catch {
    // No audio output available: the game works the same without sound.
  }
}

/** Starts or pauses the music loop to match the setting and whether the app is visible. */
function syncMusic(): void {
  const wanted = useSettingsStore.getState().music && foreground;
  try {
    if (wanted) {
      if (!music) {
        music = createAudioPlayer(require('../../assets/sounds/music.wav'));
        music.loop = true;
        music.volume = MUSIC_VOLUME;
      }
      music.play();
    } else {
      music?.pause();
    }
  } catch {
    // Same as above: silence is fine.
  }
}

let started = false;

/** Call once at startup (after the settings are loaded). */
export function initSounds(): void {
  if (started) return;
  started = true;
  // Mix with other apps' audio, and keep effects audible with the iPhone's silent switch on.
  void setAudioModeAsync({ playsInSilentMode: true, interruptionMode: 'mixWithOthers' }).catch(
    () => {},
  );
  // Preload the effects so the first one plays without delay.
  (Object.keys(EFFECTS) as SoundName[]).forEach(effectPlayer);
  syncMusic();
  useSettingsStore.subscribe((state, prev) => {
    if (state.music !== prev.music) syncMusic();
  });
  AppState.addEventListener('change', (state) => {
    foreground = state === 'active';
    syncMusic();
  });
}
